using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEditor;
using UnityEditor.Callbacks;

namespace Template.Editor
{
    /// <summary>
    /// Patches the Podfile generated by Google's External Dependency Manager, between its Podfile
    /// generation (order 40) and "pod install" (order 50):
    ///  1. CDN only: Google's dependency XMLs add the legacy git Specs repo (multi-GB clone, fails where
    ///     GitHub is blocked); the CocoaPods CDN serves the same specs.
    ///  2. Pod targets get the project's minimum iOS version: pods declare older minimums (e.g. 12.0)
    ///     that current Xcode refuses to build.
    /// </summary>
    internal static class PodfilePatcher
    {
        private const string GitSpecsSource = "source 'https://github.com/CocoaPods/Specs'";
        private const string CdnSource = "source 'https://cdn.cocoapods.org/'";
        private const string Marker = "# hc_template: align pod deployment targets";

        [PostProcessBuild(45)]
        private static void OnPostProcessBuild(BuildTarget target, string path)
        {
            if (target != BuildTarget.iOS) return;
            var podfile = Path.Combine(path, "Podfile");
            if (!File.Exists(podfile)) return;

            var lines = File.ReadAllLines(podfile).Where(l => l.Trim() != GitSpecsSource).ToList();
            if (!lines.Any(l => l.Trim() == CdnSource)) lines.Insert(0, CdnSource);

            if (!lines.Any(l => l.Contains(Marker)))
            {
                if (lines.Any(l => l.TrimStart().StartsWith("post_install")))
                {
                    Log.Warn("Podfile already has a post_install hook; pod deployment targets not aligned.");
                }
                else
                {
                    var min = PlayerSettings.iOS.targetOSVersionString;
                    lines.AddRange(new List<string>
                    {
                        "",
                        Marker,
                        "post_install do |installer|",
                        "  installer.pods_project.targets.each do |t|",
                        "    t.build_configurations.each do |c|",
                        $"      c.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '{min}'",
                        "    end",
                        "  end",
                        "end",
                    });
                }
            }

            File.WriteAllLines(podfile, lines);
            Log.Info($"Podfile patched: CocoaPods CDN only, pods target iOS {PlayerSettings.iOS.targetOSVersionString}.");
        }
    }
}
